import { useEffect, useState } from 'react';
import Home from './pages/Home.jsx';
import VoiceCall from './pages/VoiceCall.jsx';
import ClinicList from './pages/ClinicList.jsx';
import PhoneCall from './pages/PhoneCall.jsx';
import Plan from './pages/Plan.jsx';
import { strings, detectLang, saveLang } from './i18n.js';
import { primeSpeech } from './agents/speech.js';
import { buildSummary } from './utils/summary.js';

// home → voice call with Pawse → advice
//   → "call the vet": clinic list → Pawse calls the chosen clinic
//   → "call the insurer": Pawse calls the insurer
//   → plan (summary)
export default function App() {
  const [view, setView] = useState('home'); // home | voice | clinics | phone | plan
  const [lang, setLangState] = useState(detectLang);
  const [triage, setTriage] = useState(null);
  const [vet, setVet] = useState(null);
  const [insurance, setInsurance] = useState(null);
  const [clinic, setClinic] = useState(null);
  const [target, setTarget] = useState(null);

  const t = strings[lang];

  const setLang = (l) => {
    setLangState(l);
    saveLang(l);
  };

  useEffect(() => {
    document.documentElement.lang = lang === 'zh' ? 'zh-CN' : 'en';
  }, [lang]);

  const startCall = () => {
    primeSpeech(); // unlock speech on iOS while we are inside the tap
    setTriage(null);
    setVet(null);
    setInsurance(null);
    setClinic(null);
    setView('voice');
  };

  const call = (to) => {
    primeSpeech();
    if (to === 'vet') {
      setView('clinics');
      return;
    }
    setTarget(to);
    setView('phone');
  };

  const pickClinic = (c) => {
    primeSpeech();
    setClinic(c);
    setTarget('vet');
    setView('phone');
  };

  const callDone = (result) => {
    if (result && target === 'vet') setVet(result);
    if (result && target === 'insurance') setInsurance(result);
    setView(triage ? 'plan' : 'home');
  };

  if (view === 'voice') {
    return (
      <VoiceCall
        t={t}
        lang={lang}
        triage={triage}
        vet={vet}
        insurance={insurance}
        onTriage={setTriage}
        onCall={call}
        onEnd={() => setView(triage ? 'plan' : 'home')}
      />
    );
  }
  if (view === 'clinics') {
    // Going back from the list never restarts the voice call: show the plan instead.
    return <ClinicList t={t} lang={lang} triage={triage} onPick={pickClinic} onBack={() => setView(triage ? 'plan' : 'home')} />;
  }
  if (view === 'phone') {
    return (
      <PhoneCall
        key={`${target}-${clinic ? clinic.id : ''}`}
        t={t}
        lang={lang}
        target={target}
        clinic={target === 'vet' ? clinic : null}
        context={{
          summary: buildSummary({ lang, triage, vet, insurance }),
          clinic: target === 'vet' ? clinic : undefined,
          estimate: vet ? vet.estimate : undefined,
        }}
        onDone={callDone}
      />
    );
  }
  if (view === 'plan' && triage) {
    return (
      <Plan
        t={t}
        lang={lang}
        triage={triage}
        vet={vet}
        insurance={insurance}
        onCall={call}
        onRestart={() => setView('home')}
      />
    );
  }
  return <Home t={t} lang={lang} setLang={setLang} onStart={startCall} />;
}
import { useEffect, useRef, useState } from 'react';
import Avatar from '../components/Avatar.jsx';
import Icon from '../components/Icon.jsx';
import { createPhoneCall } from '../agents/index.js';
import { isSpeechMuted, setSpeechMuted } from '../agents/speech.js';
import { validateResult } from '../contracts.js';

function fmt(sec) {
  return `${String(Math.floor(sec / 60)).padStart(2, '0')}:${String(sec % 60).padStart(2, '0')}`;
}

function ResultCard({ t, target, result }) {
  if (target === 'vet') {
    return (
      <div className="result-card">
        <h3>✓ {t.appointment}</h3>
        {result.simulated && <span className="sim-badge">{t.simulated}</span>}
        <div className="result-big">{result.time}</div>
        <p>{result.place}</p>
        <p>
          {t.estimate}: <strong>≈ {result.currency || 'CHF'} {result.estimate}</strong>
        </p>
        {result.note && <p className="muted small">{result.note}</p>}
      </div>
    );
  }
  const cur = result.currency || 'CHF';
  return (
    <div className="result-card">
      <h3>{t.insuranceAnswer}</h3>
      {result.simulated && <span className="sim-badge">{t.simulated}</span>}
      <ul className="cov">
        {result.points.map((p, i) => (
          <li key={i} className={p.ok ? 'ok' : 'no'}>
            <span className="cov-icon" aria-hidden="true">{p.ok ? '✓' : '✕'}</span>
            <span>
              {p.text}
              {p.ref && <span className="ref">{p.ref}</span>}
            </span>
          </li>
        ))}
      </ul>
      <div className="money">
        <div>
          <span className="muted small">{t.reimbursed}</span>
          <strong>≈ {cur} {result.reimbursed}</strong>
        </div>
        <div>
          <span className="muted small">{t.outOfPocket}</span>
          <strong className="accent">≈ {cur} {result.outOfPocket}</strong>
        </div>
      </div>
    </div>
  );
}

export default function PhoneCall({ t, lang, target, clinic, context, onDone }) {
  const base = t.callees[target];
  const callee = clinic
    ? { ...base, name: clinic.name, role: `${clinic.distanceKm.toFixed(1)} km` }
    : base;
  const [status, setStatus] = useState('dialing');
  const [lines, setLines] = useState([]);
  const [speaking, setSpeaking] = useState('none');
  const [result, setResult] = useState(null);
  const [error, setError] = useState('');
  const [secs, setSecs] = useState(0);
  const [soundOn, setSoundOn] = useState(!isSpeechMuted());
  const callRef = useRef(null);
  const listRef = useRef(null);
  const resultRef = useRef(null);
  resultRef.current = result;

  useEffect(() => {
    const call = createPhoneCall({ target, lang, context });
    callRef.current = call;
    const off = call.on((e) => {
      switch (e.type) {
        case 'status':
          setStatus(e.state);
          break;
        case 'speaking':
          setSpeaking(e.who);
          break;
        case 'line':
          setLines((p) => [...p, e]);
          break;
        case 'result': {
          const { type, ...r } = e;
          const problems = validateResult(target, r);
          if (problems.length) console.warn('[Pawse] call result violates the contract:', problems, r);
          setResult(r);
          break;
        }
        case 'error':
          setError(e.message || '');
          break;
        default:
          break;
      }
    });
    call.start();
    return () => {
      off();
      call.hangup();
    };
    // context is captured once per call on purpose
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [target, lang]);

  useEffect(() => {
    if (status !== 'connected') return undefined;
    const id = setInterval(() => setSecs((s) => s + 1), 1000);
    return () => clearInterval(id);
  }, [status]);

  useEffect(() => {
    const el = listRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [lines, result]);

  const hangup = () => {
    callRef.current && callRef.current.hangup();
    onDone(resultRef.current);
  };

  const toggleSound = () => {
    const next = !soundOn;
    setSoundOn(next);
    setSpeechMuted(!next);
  };

  const statusText = status === 'dialing' ? t.dialing : status === 'connected' ? `${t.inCall} · ${fmt(secs)}` : t.callEnded;

  return (
    <main className="pc">
      <header className="pc-head">
        <div className={`pc-callee ${speaking === 'callee' ? 'talking' : ''} ${status === 'dialing' ? 'ringing' : ''}`}>
          <span aria-hidden="true">{callee.icon}</span>
        </div>
        <h1>{callee.name}</h1>
        <p className="muted">
          {callee.role} · {statusText}
        </p>
        <span className="pill">{t.liveTranslate}</span>
      </header>

      <div className="pc-pawse">
        <Avatar size={44} speaking={speaking === 'ai'} />
        <span>{t.aiNote}</span>
      </div>

      <section className="pc-lines" ref={listRef} aria-live="polite">
        {lines.map((l, i) => (
          <div key={i} className={`line line-${l.who}`}>
            <span className="line-who">{l.who === 'ai' ? t.pawse : callee.name}</span>
            {l.simulated && <span className="sim-badge">{t.simulated}</span>}
            <p className="line-original" lang="de">{l.original}</p>
            <p className="line-text">{l.text}</p>
          </div>
        ))}
        {result && <ResultCard t={t} target={target} result={result} />}
        {error && <p className="pc-error">{error}</p>}
      </section>

      <footer className="pc-foot">
        {result || status === 'ended' ? (
          <button type="button" className="btn primary wide" onClick={() => onDone(resultRef.current)}>
            {t.backToPawse}
          </button>
        ) : (
          <div className="pc-controls">
            <button type="button" className="pc-ctl" onClick={toggleSound} aria-pressed={!soundOn} aria-label={t.sound}>
              <Icon name={soundOn ? 'volume' : 'volumeOff'} />
            </button>
            <button type="button" className="pc-ctl hang" onClick={hangup} aria-label={t.hangup}>
              <Icon name="phone" size={28} style={{ transform: 'rotate(135deg)' }} />
            </button>
            <span className="pc-ctl-spacer" />
          </div>
        )}
      </footer>
    </main>
  );
}
// Pawse's advice + the two "let Pawse call for you" actions.
// Used as the bottom sheet on the video call and at the top of the plan page.

const GLYPH = { red: '!', yellow: '◷', green: '✓' };

function ActionRow({ icon, title, sub, doneText, button, onClick }) {
  return (
    <div className={doneText ? 'action-row done' : 'action-row'}>
      <span className="action-icon" aria-hidden="true">{icon}</span>
      <div className="action-text">
        <strong>{title}</strong>
        <span>{doneText || sub}</span>
      </div>
      <button type="button" className={doneText ? 'btn soft small' : 'btn primary small'} onClick={onClick}>
        {button}
      </button>
    </div>
  );
}

export default function PlanPanel({ t, triage, vet, insurance, onCall }) {
  if (!triage) return null;
  const vetDone = vet ? `✓ ${t.booked} ${vet.time} · ≈ ${vet.currency || 'CHF'} ${vet.estimate}` : '';
  const insDone = insurance ? `✓ ${t.outOfPocket} ≈ ${insurance.currency || 'CHF'} ${insurance.outOfPocket}` : '';

  return (
    <div className="plan-panel">
      <div className={`level level-${triage.level}`}>
        <span className="level-glyph" aria-hidden="true">{GLYPH[triage.level]}</span>
        <div>
          <span className="level-kicker">{t.adviceTitle}</span>
          <strong className="level-title">{triage.headline || t.levels[triage.level]}</strong>
        </div>
      </div>

      <section>
        <h3>{t.nowDo}</h3>
        <ul className="steps">
          {triage.steps.map((s, i) => (
            <li key={i}>{s}</li>
          ))}
        </ul>
        {triage.escalation && <p className="escalation">{triage.escalation}</p>}
      </section>

      <section>
        <h3>{t.transferTitle}</h3>
        <div className="actions">
          <ActionRow
            icon={t.callees.vet.icon}
            title={t.callVet}
            sub={t.callVetSub}
            doneText={vetDone}
            button={vet ? t.callAgain : t.call}
            onClick={() => onCall('vet')}
          />
          <ActionRow
            icon={t.callees.insurance.icon}
            title={t.callIns}
            sub={t.callInsSub}
            doneText={insDone}
            button={insurance ? t.callAgain : t.call}
            onClick={() => onCall('insurance')}
          />
        </div>
        <p className="ai-note">{t.aiNote}</p>
      </section>
    </div>
  );
}
